void apply(HelperCpu& base, const HelperCpuPatch& patch) {
    if (patch.reference) base.reference = *patch.reference;
    if (patch.affinity) base.affinity = *patch.affinity;
}

void apply(HelperRuntime& base, const HelperRuntimePatch& patch) {
    if (patch.power_save) base.power_save = *patch.power_save;
    if (patch.queue_warm) base.queue_warm = *patch.queue_warm;
}

void apply(HelperGemv& base, const HelperGemvPatch& patch) {
    if (patch.mode) base.mode = *patch.mode;
    if (patch.wide) base.wide = *patch.wide;
    if (patch.h2) base.h2 = *patch.h2;
    if (patch.w4h2) base.w4h2 = *patch.w4h2;
    if (patch.mr) base.mr = *patch.mr;
}

void apply(HelperLanes& base, const HelperLanesPatch& patch) {
    if (patch.small_lanes) base.small_lanes = *patch.small_lanes;
    if (patch.rows) base.rows = *patch.rows;
    if (patch.rows_small) base.rows_small = *patch.rows_small;
}

void apply(HelperCombine& base, const HelperCombinePatch& patch) {
    if (patch.enabled) base.enabled = *patch.enabled;
    if (patch.min_rows) base.min_rows = *patch.min_rows;
    if (patch.threads) base.threads = *patch.threads;
}

void apply(HelperKernels& base, const HelperKernelsPatch& patch) {
    if (patch.native) base.native = *patch.native;
    if (patch.fp16) base.fp16 = *patch.fp16;
    if (patch.ahalf) base.ahalf = *patch.ahalf;
    if (patch.moe_form) base.moe_form = *patch.moe_form;
    if (patch.moe_long_rows) base.moe_long_rows = *patch.moe_long_rows;
    if (patch.fuseroute) base.fuseroute = *patch.fuseroute;
    if (patch.vecio) base.vecio = *patch.vecio;
    if (patch.sparse_act) base.sparse_act = *patch.sparse_act;
    if (patch.lane_quant) base.lane_quant = *patch.lane_quant;
}

void apply(HelperPlacement& base, const HelperPlacementPatch& patch) {
    if (patch.balance) base.balance = *patch.balance;
    if (patch.balance_speeds_milli) base.balance_speeds_milli = *patch.balance_speeds_milli;
}

void apply(HelperCommon& base, const HelperPatch& patch) {
    if (patch.cpu) apply(base.cpu, *patch.cpu);
    if (patch.runtime) apply(base.runtime, *patch.runtime);
    if (patch.gemv) apply(base.gemv, *patch.gemv);
    if (patch.lanes) apply(base.lanes, *patch.lanes);
    if (patch.combine) apply(base.combine, *patch.combine);
    if (patch.kernels) apply(base.kernels, *patch.kernels);
    if (patch.placement) apply(base.placement, *patch.placement);
}

